195	
196	      {!claiming && filtered && shown.length > 0 && (
197	        <p className="text-center text-[12px] text-tx-faint">
198	          Showing {shown.length} of {rows.length} services
199	        </p>
200	      )}
201	
202	      <ServicePreviewDialog row={editing} onClose={() => setEditing(null)} />
203	    </div>
204	  );
205	}
