2	
3	import { useEffect, useId, useRef, useState } from "react";
4	
5	export type SelectOption = { key: string; label: string; hint?: string };
6	
7	/**
8	 * The toolbar's dropdown.
9	 *
10	 * A native `<select>` was here first, and its popup is drawn by the operating
11	 * system — white panel, system blue highlight — which no amount of CSS on the
12	 * control itself can reach. So this is a real listbox: a button plus a panel
13	 * we own, styled in the same language as everything around it.
14	 *
15	 * Keyboard behaviour matches the native control it replaces: Enter/Space/Down
16	 * opens, Up/Down move, Home/End jump, Enter commits, Escape cancels and returns
17	 * focus to the button, and a click outside closes without changing anything.
18	 */
19	export function FilterSelect({
20	  value, onChange, options, label, width = "w-[176px]",
21	}: {
22	  value: string;
23	  onChange: (v: string) => void;
24	  options: SelectOption[];
25	  /** Small caption above the value, as the concept's "Sort by" control has. */
26	  label?: string;
27	  width?: string;
28	}) {
29	  const [open, setOpen] = useState(false);
30	  const [active, setActive] = useState(() => Math.max(0, options.findIndex((o) => o.key === value)));
31	  const rootRef = useRef<HTMLDivElement | null>(null);
32	  const btnRef = useRef<HTMLButtonElement | null>(null);
33	  const listRef = useRef<HTMLUListElement | null>(null);
34	  const listId = useId();
35	
36	  const current = options.find((o) => o.key === value) ?? options[0];
37	
38	  useEffect(() => {
39	    if (!open) return;
40	    const onDown = (e: MouseEvent) => {
41	      if (!rootRef.current?.contains(e.target as Node)) setOpen(false);
42	    };
43	    document.addEventListener("mousedown", onDown);
44	    return () => document.removeEventListener("mousedown", onDown);
45	  }, [open]);
46	
47	  // Keep the highlighted row in view when the list is longer than the panel.
48	  useEffect(() => {
49	    if (!open) return;
50	    listRef.current?.querySelector<HTMLElement>('[data-active="true"]')
51	      ?.scrollIntoView({ block: "nearest" });
52	  }, [open, active]);
53	
54	  const commit = (i: number) => {
55	    const opt = options[i];
56	    if (opt) onChange(opt.key);
57	    setOpen(false);
58	    btnRef.current?.focus();
59	  };
60	
61	  const onKeyDown = (e: React.KeyboardEvent) => {
62	    if (!open) {
63	      if (e.key === "Enter" || e.key === " " || e.key === "ArrowDown") {
64	        e.preventDefault();
65	        setActive(Math.max(0, options.findIndex((o) => o.key === value)));
66	        setOpen(true);
67	      }
68	      return;
69	    }
70	    switch (e.key) {
71	      case "Escape": e.preventDefault(); setOpen(false); btnRef.current?.focus(); break;
72	      case "ArrowDown": e.preventDefault(); setActive((i) => Math.min(options.length - 1, i + 1)); break;
73	      case "ArrowUp": e.preventDefault(); setActive((i) => Math.max(0, i - 1)); break;
74	      case "Home": e.preventDefault(); setActive(0); break;
75	      case "End": e.preventDefault(); setActive(options.length - 1); break;
76	      case "Enter": case " ": e.preventDefault(); commit(active); break;
77	      case "Tab": setOpen(false); break;
78	    }
79	  };
80	
81	  return (
82	    <div ref={rootRef} className={"relative flex-none " + width}>
83	      <button
84	        ref={btnRef}
85	        type="button"
86	        role="combobox"
87	        aria-haspopup="listbox"
88	        aria-expanded={open}
89	        aria-controls={open ? listId : undefined}
90	        aria-label={label ?? current?.label}
91	        onClick={() => { setActive(Math.max(0, options.findIndex((o) => o.key === value))); setOpen((v) => !v); }}
92	        onKeyDown={onKeyDown}
93	        className={
94	          "flex h-[46px] w-full items-center gap-2 rounded-[12px] border px-3.5 text-left transition " +
95	          (open
96	            ? "border-[#8b5cff]/70 bg-[rgba(12,22,54,.92)]"
97	            : "border-rim-hi bg-[rgba(6,14,36,.72)] hover:border-brand-400/40")
98	        }
99	      >
100	        <span className="flex min-w-0 flex-col leading-none">
101	          {label && <span className="mb-[3px] text-[10px] font-semibold text-tx-faint">{label}</span>}
102	          <span className="truncate text-[13px] font-semibold text-white/90">{current?.label ?? ""}</span>
103	        </span>
104	        <svg
105	          aria-hidden width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor"
106	          strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"
107	          className={"ml-auto flex-none text-tx-faint transition-transform " + (open ? "rotate-180" : "")}
108	        >
109	          <path d="m6 9 6 6 6-6" />
110	        </svg>
111	      </button>
112	
113	      {open && (
114	        <ul
115	          ref={listRef}
116	          id={listId}
117	          role="listbox"
118	          aria-label={label ?? current?.label}
119	          tabIndex={-1}
120	          onKeyDown={onKeyDown}
121	          className="absolute left-0 right-0 top-[52px] z-40 max-h-[288px] overflow-y-auto rounded-[13px] border border-[#2a3f7a] bg-[#060f28] p-1.5 shadow-[0_24px_50px_-20px_rgba(0,0,0,.85)]"
122	        >
123	          {options.map((o, i) => {
124	            const selected = o.key === value;
125	            return (
126	              <li key={o.key}>
127	                <button
128	                  type="button"
129	                  role="option"
130	                  aria-selected={selected}
131	                  data-active={i === active}
132	                  onMouseEnter={() => setActive(i)}
133	                  onClick={() => commit(i)}
134	                  className={
135	                    "flex w-full items-center gap-2 rounded-[9px] px-2.5 py-2 text-left text-[13px] transition " +
136	                    (i === active ? "bg-[#7b3fef]/22 text-white" : "text-tx-dim")
137	                  }
138	                >
139	                  <span className="min-w-0 flex-1 truncate">{o.label}</span>
140	                  {o.hint && <span className="flex-none text-[11.5px] text-tx-faint">{o.hint}</span>}
141	                  {selected && (
142	                    <svg aria-hidden width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor"
143	                         strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className="flex-none text-[#c4a6ff]">
144	                      <path d="M20 6 9 17l-5-5" />
145	                    </svg>
146	                  )}
147	                </button>
148	              </li>
149	            );
150	          })}
151	        </ul>
152	      )}
153	    </div>
154	  );
155	}
