13	export const STATUS_STYLE: Record<ServiceStatus, { dot: string; ink: string; chip: string }> = {
14	  running:   { dot: "bg-emerald-400", ink: "text-emerald-300", chip: "border-emerald-400/30 bg-emerald-950/70" },
15	  pending:   { dot: "bg-amber-400 animate-pulse", ink: "text-amber-300", chip: "border-amber-400/30 bg-amber-950/70" },
16	  stopped:   { dot: "bg-rose-400", ink: "text-rose-300", chip: "border-rose-400/30 bg-rose-950/70" },
17	  suspended: { dot: "bg-orange-400", ink: "text-orange-300", chip: "border-orange-400/30 bg-orange-950/70" },
18	  error:     { dot: "bg-red-400", ink: "text-red-300", chip: "border-red-400/30 bg-red-950/70" },
19	  cancelled: { dot: "bg-slate-400", ink: "text-slate-300", chip: "border-slate-400/25 bg-slate-950/70" },
20	};
21	
22	/** The service mark that sits under the preview, one per product. */
23	const KIND_MARK: Record<ServiceRow["kind"], { mark: string; ring: string }> = {
24	  vps:     { mark: "vps",     ring: "border-[#3d7bff]/40 bg-[#3d7bff]/12" },
25	  game:    { mark: "game",    ring: "border-[#a86bff]/40 bg-[#a86bff]/12" },
26	  hosting: { mark: "hosting", ring: "border-[#3ec9ff]/40 bg-[#3ec9ff]/12" },
27	  free:    { mark: "game",    ring: "border-emerald-500/40 bg-emerald-500/12" },
28	};
29	
30	function fmtDate(iso: string): string {
31	  return new Date(iso).toLocaleDateString("en-US", {
32	    year: "numeric", month: "short", day: "numeric", timeZone: "UTC",
33	  });
34	}
35	
36	/** How the renewal total is qualified. `renewalCharge` returns the charge for
37	 *  the WHOLE term, and a term can be 1, 3, 12, 24 or 36 months, so anything but
38	 *  "/mo" and "/yr" has to say how many months it actually buys. */
39	function termSuffix(months: number): string {
40	  if (months === 12) return "/yr";
41	  if (months <= 1) return "/mo";
42	  if (months % 12 === 0) return `/${months / 12}yr`;
43	  return `/${months}mo`;
44	}
45	
46	function daysUntil(iso: string): number {
47	  return Math.ceil((new Date(iso).getTime() - Date.now()) / 86_400_000);
48	}
49	
50	/* ── the picture every card leads with ────────────────────────────────────
51	   A stock plate underneath, and — for a live hosting plan — the customer's
52	   own site framed over it. The frame is inert: no scripts, no pointer
53	   events, no tab stop. A site that refuses to be framed simply never paints,
54	   and the plate stays. Nothing here stands in for a site that isn't there. */
55	function Preview({ row }: { row: ServiceRow }) {
56	  return (
57	    <span className="relative block h-full w-full overflow-hidden bg-[#050d20]">
58	      {/* eslint-disable-next-line @next/next/no-img-element -- art + customer uploads, both outside the optimizer */}
59	      <img
60	        src={row.previewSrc}
61	        alt=""
62	        aria-hidden
63	        loading="lazy"
64	        className="h-full w-full object-cover transition duration-500 group-hover:scale-[1.04]"
65	      />
66	      {row.siteToFrame && (
67	        <iframe
68	          src={`https://${row.siteToFrame}/`}
69	          title=""
70	          aria-hidden
