118	  useEffect(() => {
119	    if (!open) return;
120	    const close = () => setOpen(false);
121	    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") setOpen(false); };
122	    // A fixed panel would drift away from its button on scroll, so close
123	    // instead of chasing it.
124	    window.addEventListener("scroll", close, true);
125	    window.addEventListener("resize", close);
126	    document.addEventListener("keydown", onKey);
127	    return () => {
128	      window.removeEventListener("scroll", close, true);
129	      window.removeEventListener("resize", close);
130	      document.removeEventListener("keydown", onKey);
131	    };
132	  }, [open]);
