11	/** What the card's picture is rendered at, so an upload is stored at the size
12	 *  it will actually be shown rather than at whatever the camera produced. */
13	const OUT_W = 1440;
14	const OUT_H = 450;
15	
16	/**
17	 * Downscale and re-encode in the browser before uploading.
18	 *
19	 * Two reasons this happens client-side: a phone photo is several megabytes of
20	 * detail this card will never show, and `sharp` is only a transitive dependency
21	 * here — there is no image pipeline on the server to rely on. The server still
22	 * validates the real bytes it receives; this only keeps the upload small.
23	 */
24	async function toCardImage(file: File): Promise<File> {
25	  const bitmap = await createImageBitmap(file);
26	  const canvas = document.createElement("canvas");
27	  canvas.width = OUT_W;
28	  canvas.height = OUT_H;
29	  const ctx = canvas.getContext("2d");
30	  if (!ctx) return file;
31	
32	  // Cover: fill the frame, crop the overflow, never letterbox or squash.
33	  const scale = Math.max(OUT_W / bitmap.width, OUT_H / bitmap.height);
34	  const w = bitmap.width * scale;
35	  const h = bitmap.height * scale;
36	  ctx.imageSmoothingQuality = "high";
37	  ctx.drawImage(bitmap, (OUT_W - w) / 2, (OUT_H - h) / 2, w, h);
38	  bitmap.close();
39	
40	  const blob = await new Promise<Blob | null>((res) => canvas.toBlob(res, "image/webp", 0.88));
41	  if (!blob) return file;
42	  return new File([blob], "preview.webp", { type: "image/webp" });
43	}
