45	export function ServicePreviewDialog({ row, onClose }: { row: ServiceRow | null; onClose: () => void }) {
46	  const router = useRouter();
47	  const inputRef = useRef<HTMLInputElement | null>(null);
48	  const [busy, setBusy] = useState(false);
49	  const [error, setError] = useState<string | null>(null);
50	  const [localPreview, setLocalPreview] = useState<string | null>(null);
51	  const [mounted, setMounted] = useState(false);
52	
53	  useEffect(() => setMounted(true), []);
54	
55	  useEffect(() => {
56	    if (!row) return;
57	    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); };
58	    document.addEventListener("keydown", onKey);
59	    const prev = document.body.style.overflow;
60	    document.body.style.overflow = "hidden";
61	    return () => {
62	      document.removeEventListener("keydown", onKey);
63	      document.body.style.overflow = prev;
64	    };
65	  }, [row, onClose]);
66	
67	  // Revoke the object URL rather than leaking one per file the customer tries.
68	  useEffect(() => () => { if (localPreview) URL.revokeObjectURL(localPreview); }, [localPreview]);
69	
70	  if (!row || !mounted) return null;
71	
72	  const pick = async (file: File) => {
73	    setError(null);
74	    setBusy(true);
75	    try {
76	      const shaped = await toCardImage(file);
77	      if (localPreview) URL.revokeObjectURL(localPreview);
78	      setLocalPreview(URL.createObjectURL(shaped));
79	
80	      const form = new FormData();
81	      form.set("file", shaped);
82	      const res = await setServicePreview(row.id, form);
83	      if (!res.ok) { setError(res.error); return; }
84	      router.refresh();
85	      onClose();
86	    } catch {
87	      setError("That image couldn't be read. Try a PNG, JPEG or WEBP.");
88	    } finally {
89	      setBusy(false);
90	    }
91	  };
92	
93	  return createPortal(
94	    <div
95	      className="fixed inset-0 z-[120] flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm"
96	      onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
97	    >
98	      <div
99	        role="dialog"
100	        aria-modal="true"
101	        aria-label={`Card image for ${row.name}`}
102	        className="w-full max-w-[520px] overflow-hidden rounded-[18px] border border-rim-hi bg-surface shadow-2xl"
103	      >
104	        <div className="flex items-center gap-3 border-b border-rim-soft px-5 py-4">
105	          <span className="flex min-w-0 flex-col">
106	            <h2 className="truncate text-[16px] font-extrabold text-white">Card image</h2>
107	            <p className="truncate text-[12.5px] text-tx-dim">{row.name}</p>
108	          </span>
109	          <button
110	            type="button"
