113	            className="ml-auto grid h-[32px] w-[32px] flex-none place-items-center rounded-[9px] text-tx-faint transition hover:bg-white/[0.06] hover:text-white"
114	          >
115	            <Icon name="xcircle" size={16} tone="inherit" />
116	          </button>
117	        </div>
118	
119	        <div className="p-5">
120	          <div className="aspect-[16/4] w-full overflow-hidden rounded-[13px] border border-rim-hi bg-[#050d20]">
121	            {/* eslint-disable-next-line @next/next/no-img-element -- a local object URL / customer upload */}
122	            <img src={localPreview ?? row.previewSrc} alt="" aria-hidden className="h-full w-full object-cover" />
123	          </div>
124	
125	          <p className="mt-3.5 text-[12.5px] leading-relaxed text-tx-dim">
126	            Choose an image for this service&apos;s card. It is cropped to fit and only ever
127	            visible to you. PNG, JPEG, GIF or WEBP, up to 5&nbsp;MB.
128	          </p>
129	
130	          {error && (
131	            <p className="mt-3 rounded-[10px] border border-red-500/35 bg-red-500/10 px-3 py-2 text-[12.5px] text-red-300">
132	              {error}
133	            </p>
134	          )}
135	
136	          <input
137	            ref={inputRef}
138	            type="file"
139	            accept={ACCEPT_ATTR}
