67	        style={style}
68	        fill={vector.fill ? "currentColor" : "none"}
69	        stroke={vector.fill ? "none" : "currentColor"}
70	        strokeWidth={strokeWidth}
71	        strokeLinecap="round"
72	        strokeLinejoin="round"
