79	  const [row, col] = SPR[name] ?? SPR.grid;
80	  return (
81	    <span
82	      aria-hidden
83	      className={"inline-block flex-none bg-no-repeat " + className}
84	      style={{
85	        width: s, height: s,
86	        backgroundImage: "url(/nx/nxicons.webp)",
87	        backgroundSize: `${20 * s}px ${7 * s}px`,
88	        backgroundPosition: `-${col * s}px -${row * s}px`,
89	        ...style,
90	      }}
91	    />
92	  );
