import { chromium } from "playwright";
const B = "https://v2.q4w8zt3ky6vn2sm.nxeon.cloud";
const b = await chromium.launch();
const ctx = await b.newContext({ viewport: { width: 1600, height: 1100 }, deviceScaleFactor: 1 });
const p = await ctx.newPage();
const errs = [];
p.on("console", (m) => { if (m.type() === "error") errs.push(m.text().slice(0, 200)); });

await p.goto(B + "/login", { waitUntil: "domcontentloaded", timeout: 90000 });
await p.fill('input[type="email"], input[name="email"]', "customer@nxeon.local");
await p.fill('input[type="password"], input[name="password"]', "wGPZqhCbsLdz");
await Promise.all([
  p.waitForURL((u) => !u.pathname.includes("/login"), { timeout: 45000 }).catch(() => {}),
  p.click("button.btn-primary"),
]);

// ── DARK (default) ──────────────────────────────────────────────────────
await p.goto(B + "/dashboard/services", { waitUntil: "networkidle", timeout: 90000 });
await p.waitForTimeout(2500);
await p.screenshot({ path: "/tmp/svc-dark.png", fullPage: true });

// ── LIGHT ────────────────────────────────────────────────────────────────
await p.evaluate(() => {
  localStorage.setItem("nx-theme", "light");
  document.documentElement.setAttribute("data-theme", "light");
});
await p.reload({ waitUntil: "networkidle", timeout: 90000 });
await p.waitForTimeout(2500);
await p.screenshot({ path: "/tmp/svc-light.png", fullPage: true });

// Close-up of the card row (Manage button) in light mode
const card = p.locator("article").first();
if (await card.count()) {
  await card.scrollIntoViewIfNeeded();
  await p.waitForTimeout(300);
  await card.screenshot({ path: "/tmp/svc-light-card.png" });
}

// Free Services tab in light mode
await p.click('button:has-text("Free Services")').catch(() => {});
await p.waitForTimeout(1200);
await p.screenshot({ path: "/tmp/svc-light-free.png", fullPage: true });

console.log("errors:", errs.length ? errs.join(" ~ ") : "none");
await b.close();

