489	  --color-rose: #ef426c;
490	
491	  --color-slate-50: #ffffff;
492	  --color-slate-100: #eaf2ff;
493	  --color-slate-200: #d8e6ff;
494	  --color-slate-300: #cbdcff;
495	  --color-slate-400: #93aede;
496	  --color-slate-500: #7f9ad0;
497	  --color-slate-600: #5f7cb4;
498	  --color-slate-700: #2b4a80;
499	  --color-slate-800: #001a3d;
500	  --color-slate-900: #00102a;
501	  --color-slate-950: #000816;
502	
503	  --color-tx: #ffffff;
504	  --color-tx-body: #cbdcff;
505	  --color-tx-mute: #93aede;
506	  --color-tx-dim: #7f9ad0;
507	  --color-tx-faint: #5f7cb4;
508	
509	  --fg: #ffffff;
510	  --fg-muted: #94a3b8;
511	
512	  /* Islands paint an opaque ground. Their own classes are translucent
513	     (`bg-side/80`, `bg-bg/70`) so that the dark page shows through in dark
514	     mode; over a light page that same transparency let white through and made
515	     them read grey. This puts a solid dark plate behind them. */
516	  background-color: #00081a;
517	
518	  /* The islands are still dark, so white is white again inside them. */
519	  --color-white: #ffffff;
520	
521	  /* An inherited colour, not just tokens. `body` carries `text-slate-300` and
522	     sits OUTSIDE every island, so any element inside one that does not set its
523	     own colour — most headings do not — was inheriting the LIGHT ink straight
524	     past the island's token overrides. Restating it here gives the subtree a
525	     dark-theme default to inherit from. */
526	  color: #cbdcff;
527	}
528	
529	/* /admin and /staff keep the original design. The shell there carries
530	   `.nx-dark-island`, but the page GROUND is painted on <body>, outside it — so
531	   without this the chrome would be dark on a light field. */
532	html[data-theme="light"]:has(.nx-dark-island.min-h-screen) body {
533	  background-color: #000816;
534	  background-image:
535	    radial-gradient(920px 540px at 88% -12%, rgba(0, 80, 242, 0.15), transparent 62%),
536	    radial-gradient(700px 460px at 6% 108%, rgba(80, 40, 220, 0.11), transparent 66%);
537	}
538	
539	/* ── surfaces that draw their own colour ───────────────────────────────────
540	   A handful of components paint gradients or translucent fills directly rather
541	   than through a token. Those need a light counterpart; everything else is
542	   already correct from the swap above. */
543

543	
544	/* .card's border is a dark blue gradient in border-box. On paper that reads as
545	   a dirty outline, so light mode takes a plain rim and a real shadow instead —
546	   depth from the lift, not from the edge. */
547	/* :not(.card-on) — the selected-plan card (game/VPS deploy wizard) paints its
548	   own rainbow conic-gradient rim and dark fill regardless of theme, same idea
549	   as an nx-dark-island. This rule has higher specificity than `.card-on`
550	   alone (html + class + :not() beats one class), so without the exclusion it
551	   silently overwrote the selected treatment with the plain unselected card
552	   style — every plan card looked identical and nothing showed as picked. */
553	html[data-theme="light"] .card:not(.nx-dark-island .card):not(.card-on) {
554	  background: var(--color-surface);
555	  border: 1px solid var(--color-rim);
556	  box-shadow: 0 1px 2px rgb(15 23 42 / 0.05), 0 14px 32px -22px rgb(15 23 42 / 0.30);
557	}
558	html[data-theme="light"] .card-i:hover:not(.card-on) {
559	  background: #ffffff;
560	  border-color: color-mix(in srgb, var(--color-brand-500) 34%, transparent);
561	  box-shadow: 0 2px 4px rgb(15 23 42 / 0.06), 0 18px 38px -20px rgb(15 23 42 / 0.34);
562	}
563	
564	/* Glass over a light page needs a fill to be glass at all — fully transparent
565	   on white is just white. A high-key wash keeps the blur legible. */
566	html[data-theme="light"] .card-glass {
567	  background: rgba(255, 255, 255, 0.66);
568	  border-color: color-mix(in srgb, var(--tone) 42%, transparent);
569	  box-shadow: 0 10px 26px rgba(15, 23, 42, 0.12);
570	}
571	html[data-theme="light"] .card-glass::before { opacity: 0.55; }
572	
573	/* :not(.nx-dark-island .glass) — the promo carousel's sheet is a `.glass`
574	   sitting over its OWN photographic artwork and scrim, tuned with literal
575	   pale-blue/white text throughout (never page tokens), same as a hero. The
576	   unscoped version of this rule turned it into a bright white pane with
577	   still-white text on top of it — invisible, not readable. */
578	html[data-theme="light"] .glass:not(.nx-dark-island .glass),
579	html[data-theme="light"] .glass-sm:not(.nx-dark-island .glass-sm) {
580	  background: rgba(255, 255, 255, 0.72);
581	  border-color: var(--color-rim);
582	}
583	
584	html[data-theme="light"] .well { background: var(--color-well); }
585	
586	html[data-theme="light"] .field,
587	html[data-theme="light"] .input {
588	  background: #ffffff;
589	  border-color: var(--color-rim);
590	  color: var(--color-tx);
591	}
592	
593	/* .chip-q / .chip-q-on (referral-row status pills: "Awaiting first
594	   purchase" / "$X credited") are a literal near-black glass fill with pale
595	   ice-blue text, tuned for sitting on a dark row. On paper the near-black
596	   fill only reads as a faint grey smudge and the pale text drops to almost
597	   no contrast against it — the low-contrast pills reported on /dashboard/refer.
598	   Light mode gets a real tinted-glass fill with dark, saturated text instead
599	   of trying to reuse the dark values at a different opacity. */
600	html[data-theme="light"] .chip-q {
601	  background: var(--color-well);
602	  border-color: var(--color-rim-hi);
603	  color: var(--color-tx-dim);
604	}
605	html[data-theme="light"] .chip-q-on {
606	  color: var(--color-accent-cyan);
607	  border-color: color-mix(in srgb, var(--color-cyan) 45%, transparent);
608	  background: color-mix(in srgb, var(--color-cyan) 12%, var(--color-well));
609	  box-shadow: none;
610	}
