input.new_string:
/* My Services (components/customer/services/ServiceCard.tsx) — the card's
   "Manage" CTA is a literal navy-blue glass gradient tuned to sit on the
   card's own dark gradient face. Reported as "a flat, ugly, low-contrast
   mid-slate-blue button": on the light page the translucent navy blends down
   to a flat medium slate-blue with a white label on top, instead of reading
   as a button at all. Scoped to its own class (not the shared rgba pattern
   above, which several other pages' hero buttons also use and are not part
   of this fix) so only this card's CTA moves; dark mode is untouched since
   this selector only exists under [data-theme=light]. */
html[data-theme="light"] .nx-svc-manage {
  background: color-mix(in srgb, var(--fg) 6%, transparent) !important;
  border-color: var(--color-rim-hi) !important;
  color: var(--color-tx) !important;
}
html[data-theme="light"] .nx-svc-manage:hover {
  background: color-mix(in srgb, var(--fg) 11%, transparent) !important;
  border-color: var(--color-brand-400) !important;
}

/* app/dashboard/services/page.tsx's hero eyebrow line ("SAME INFRASTRUCTURE.
   A BRIGHTER TOMORROW.", also reused verbatim on Migrate and Settings) is a
   pale violet tuned to sit on the dark hero-racks photo. On the light page
   that same violet nearly vanishes against the (also lightened) photo and the
   page ground behind it. Retinted through the theme's own violet accent,
   which is already calibrated for contrast on paper. */
html[data-theme="light"] [class*="text-[#a892ff]"] {
  color: var(--color-violet);
}

